// Entry point of the Worker: wraps the OpenNext handler.
//
// `Cache-Control: no-transform` on HTML stops Cloudflare from injecting its Web Analytics
// beacon (enabled zone-wide for maximilianauer.at), so Pacepact stays free of tracking
// as promised in the privacy notice.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

export default {
  async fetch(request: Request, env: unknown, ctx: ExecutionContext): Promise<Response> {
    const response: Response = await handler.fetch(request, env, ctx);
    if (!(response.headers.get("content-type") ?? "").includes("text/html")) return response;
    const out = new Response(response.body, response);
    const cc = out.headers.get("cache-control");
    if (!cc?.includes("no-transform")) out.headers.set("cache-control", cc ? `${cc}, no-transform` : "no-transform");
    return out;
  },
} satisfies ExportedHandler;
